 p_id=>wwv_flow_imp.id(39239525053453857408)
,p_plug_name=>'12x1'
,p_static_id=>'12x1'
,p_title=>'How to do it?'
,p_parent_plug_id=>wwv_flow_imp.id(39239524976878857407)
,p_region_template_options=>'#DEFAULT#:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p> Simply add the code below inside the JavaScript Initialization Function attribute of your calendar region: </p>',
'<code>',
'function (config) {',
'    // 1. Set default view to Full-Year Multi-Month layout',
'    config.initialView = ''multiMonthYear'';',
'    config.endDateExclusive = false;',
'    ',
'    // 2. GRID LAYOUT CONTROL:',
'    // Change this value to adjust the number of columns per row.',
'    // Total months (12) / Columns = Number of rows.',
'    //',
'    // For 6x2 (6 rows x 2 columns): set to 2',
'    // For 4x3 (4 rows x 3 columns): set to 3',
'    // For 3x4 (3 rows x 4 columns): set to 4',
'    // For 12x1 (12 rows x 1 column stacked): set to 1',
'    // For 1x12 (1 row x 12 columns inline): set to 12',
'    config.multiMonthMaxColumns = 1;',
'',
'    // 3. Lifecycle hook to prevent Oracle APEX from resetting back to the default view',
'    var originalViewDidMount = config.viewDidMount;',
'    config.viewDidMount = function(info) {',
'        if (originalViewDidMount) {',
'            originalViewDidMount(info);',
'        }',
'        // Force back to multiMonthYear if APEX attempts an override',
'        if (info.view.type !== ''multiMonthYear'') {',
'            info.view.calendar.changeView(''multiMonthYear'');',
'        }',
'    };',
'',
'    return config;',
'}',
'</code>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260918121847Z')
,p_updated_on=>wwv_flow_imp.dz('20260918121848Z')
