'    var currentYear = new Date().getFullYear();',
'',
'    // 2. Set starting point to January 1st (mm-dd) of current year',
'    config.initialDate = currentYear + ''-01-01'';',
'',
'    // 3. Include full end date for multi-day events',
'    config.endDateExclusive = false;',
'',
'    // 4. Remove right toolbar buttons',
'    if (config.headerToolbar) {',
'        config.headerToolbar.end = "";',
'    }',
'',
'    // 5. Set custom initial view',
'    config.initialView = ''multiMonthJanToMay'';',
'',
'    // 6. 2 columns per row layout',
'    config.multiMonthMaxColumns = 2;',
'',
'    // 7. Define custom view with 4 months duration',
'    config.views = {',
'        multiMonthJanToMay: {',
'            type: ''multiMonthYear'',',
'            duration: { months: 4 }',
'        }',
'    };',
'',
'    // 8. Safe DOM hook with timeout to prevent ''getBoundingClientRect'' null error',
'    var originalViewDidMount = config.viewDidMount;',
'    config.viewDidMount = function(info) {',
'        if (originalViewDidMount) {',
'            originalViewDidMount(info);',
'        }',
'        if (info.view.type !== ''multiMonthJanToMay'') {',
'            setTimeout(function() {',
'                if (info.view && info.view.calendar) {',
'                    info.view.calendar.changeView(''multiMonthJanToMay'');',
'                }',
'            }, 0);',
'        }',
'    };',
'',
'    return config;',
'}'))
